1	package com.example.starter.calibration.repo;
2	
3	import java.sql.PreparedStatement;
4	import java.sql.Statement;
5	import java.time.Instant;
6	import java.time.LocalDateTime;
7	import java.util.Optional;
8	
9	import org.springframework.dao.DuplicateKeyException;
10	import org.springframework.jdbc.core.JdbcTemplate;
11	import org.springframework.jdbc.core.RowMapper;
12	import org.springframework.jdbc.support.GeneratedKeyHolder;
13	import org.springframework.jdbc.support.KeyHolder;
14	import org.springframework.stereotype.Repository;
15	
16	import com.example.starter.calibration.model.Certificate;
17	
18	/**
19	 * 校准证书持久化。证书创建后不可修改，仅可撤销；
20	 * 同一仪器的创建通过 instrument_lock 行锁串行化，保证并发下重叠区间最多一张成功。
21	 */
22	@Repository
23	public class CertificateRepository {
24	
25	    private static final RowMapper<Certificate> MAPPER = (rs, rowNum) -> new Certificate(
26	            rs.getLong("id"),
27	            rs.getString("instrument_id"),
28	            JdbcTimes.fromDb(rs.getObject("valid_from", LocalDateTime.class)),
29	            JdbcTimes.fromDb(rs.getObject("valid_to", LocalDateTime.class)),
30	            rs.getBigDecimal("coeff_a"),
31	            rs.getBigDecimal("offset_b"),
32	            rs.getBoolean("revoked"),
33	            JdbcTimes.fromDb(rs.getObject("revoked_at", LocalDateTime.class)),
34	            JdbcTimes.fromDb(rs.getObject("created_at", LocalDateTime.class)));
35	
36	    private final JdbcTemplate jdbc;
37	
38	    public CertificateRepository(JdbcTemplate jdbc) {
39	        this.jdbc = jdbc;
40	    }
41	
42	    /**
43	     * 获取仪器级互斥锁（须在事务内调用）：不存在锁行则插入，随后对该行 FOR UPDATE。
44	     */
45	    public void lockInstrument(String instrumentId) {
46	        try {
47	            jdbc.update("INSERT INTO instrument_lock (instrument_id, created_at) VALUES (?, ?)",
48	                    instrumentId, JdbcTimes.toDb(Instant.now()));
49	        } catch (DuplicateKeyException ignored) {
50	            // 锁行已存在，直接进入行锁等待
51	        }
52	        jdbc.queryForObject("SELECT instrument_id FROM instrument_lock WHERE instrument_id = ? FOR UPDATE",
53	                String.class, instrumentId);
54	    }
55	
56	    /**
57	     * 插入证书并返回生成的证书 ID。
58	     */
59	    public long insert(String instrumentId, Instant validFrom, Instant validTo,
60	                       java.math.BigDecimal a, java.math.BigDecimal b, Instant createdAt) {
61	        KeyHolder keyHolder = new GeneratedKeyHolder();
62	        jdbc.update(con -> {
63	            PreparedStatement ps = con.prepareStatement(
64	                    "INSERT INTO calibration_certificate "
65	                            + "(instrument_id, valid_from, valid_to, coeff_a, offset_b, revoked, created_at) "
66	                            + "VALUES (?, ?, ?, ?, ?, FALSE, ?)",
67	                    Statement.RETURN_GENERATED_KEYS);
68	            ps.setString(1, instrumentId);
69	            ps.setObject(2, JdbcTimes.toDb(validFrom));
70	            ps.setObject(3, JdbcTimes.toDb(validTo));
71	            ps.setBigDecimal(4, a);
72	            ps.setBigDecimal(5, b);
73	            ps.setObject(6, JdbcTimes.toDb(createdAt));
74	            return ps;
75	        }, keyHolder);
76	        return keyHolder.getKey().longValue();
77	    }
78	
79	    /**
80	     * 按 ID 查询（不加锁）。
81	     */
82	    public Optional<Certificate> findById(long id) {
83	        return jdbc.query("SELECT * FROM calibration_certificate WHERE id = ?", MAPPER, id)
84	                .stream().findFirst();
85	    }
86	
87	    /**
88	     * 按 ID 查询并加行锁（须在事务内调用），用于撤销与放行的并发互斥。
89	     */
90	    public Optional<Certificate> findByIdForUpdate(long id) {
91	        return jdbc.query("SELECT * FROM calibration_certificate WHERE id = ? FOR UPDATE", MAPPER, id)
92	                .stream().findFirst();
93	    }
94	
95	    /**
96	     * 统计同一仪器下与 [from, to) 重叠的未撤销证书数量；相邻区间（端点相接）不算重叠。
97	     */
98	    public int countActiveOverlap(String instrumentId, Instant from, Instant to) {
99	        Integer count = jdbc.queryForObject(
100	                "SELECT COUNT(*) FROM calibration_certificate "
101	                        + "WHERE instrument_id = ? AND revoked = FALSE AND valid_from < ? AND valid_to > ?",
102	                Integer.class, instrumentId, JdbcTimes.toDb(to), JdbcTimes.toDb(from));
103	        return count == null ? 0 : count;
104	    }
