20	@SpringBootTest
21	@AutoConfigureMockMvc
22	class MeasurementSubmitTest {
23	
24	    @Autowired
25	    private MockMvc mvc;
26	
27	    @Autowired
28	    private JdbcTemplate jdbc;
29	
30	    @BeforeEach
31	    void clean() {
32	        jdbc.update("DELETE FROM release_record");
33	        jdbc.update("DELETE FROM measurement");
34	        jdbc.update("DELETE FROM calibration_certificate");
35	        jdbc.update("DELETE FROM instrument_lock");
36	    }
37	
38	    private void createCert(String instrument, String from, String to, String a, String b) throws Exception {
39	        String json = """
40	                {"instrumentId":"%s","validFrom":"%s","validTo":"%s","a":"%s","b":"%s"}
41	                """.formatted(instrument, from, to, a, b);
42	        mvc.perform(post("/api/certificates").contentType(MediaType.APPLICATION_JSON).content(json))
43	                .andExpect(status().isCreated());
44	    }
45	
46	    private String measurementJson(String key, String instrument, String at, String reading,
47	                                   String lower, String upper, String by) {
48	        return """
49	                {"measurementKey":"%s","instrumentId":"%s","measuredAt":"%s","reading":"%s",
50	                 "lowerLimit":"%s","upperLimit":"%s","submittedBy":"%s"}
51	                """.formatted(key, instrument, at, reading, lower, upper, by);
52	    }
53	
54	    @Test
55	    void submitComputesExactValueAndHalfUpDisplayAndPendingStatus() throws Exception {
56	        // 1.5 × 2.000001 + 0.123456 = 3.1234575（精确）；显示值 HALF_UP 4 位 = 3.1235
57	        createCert("INS-1", "2026-01-01T00:00:00Z", "2027-01-01T00:00:00Z", "1.5", "0.123456");
58	        mvc.perform(post("/api/measurements").contentType(MediaType.APPLICATION_JSON)
59	                        .content(measurementJson("M-1", "INS-1", "2026-06-01T00:00:00Z",
60	                                "2.000001", "0", "3.123458", "alice")))
61	                .andExpect(status().isCreated())
62	                .andExpect(jsonPath("$.computedValue").value("3.1234575"))
63	                .andExpect(jsonPath("$.displayValue").value("3.1235"))
64	                .andExpect(jsonPath("$.passed").value(true))
65	                .andExpect(jsonPath("$.status").value("PENDING"))
66	                .andExpect(jsonPath("$.usable").value(false))
67	                .andExpect(jsonPath("$.certificateId").isNumber())
68	                .andExpect(jsonPath("$.releases").isArray());
69	    }
