            ps.setString(5, config.updatedBy());
            ps.setObject(6, JdbcTimes.toDb(config.createdAt()));
            ps.setObject(7, JdbcTimes.toDb(config.updatedAt()));
            return ps;
        }, keyHolder);
        return keyHolder.getKey().longValue();
